/*
 * NEON//RUNNER 霓虹夜行 —— SealChat 赛博朋克 UI Package
 * ------------------------------------------------------------
 * 视觉：酸性黄 + 冰青 + 警报红，切角面板、扫描线、透视网格地面、终端 HUD。
 * 夜间为「霓虹夜行」，日间为「镀铬白昼」。
 *
 * 配套脚本 theme-neon-runner.js 负责 HUD、开机序列、信号到达特效与标题故障。
 * 不加载脚本时本 CSS 独立可用；所有脚本增强样式都限定在
 * html[data-sc-theme='neon-runner'] 下。
 *
 * 稳定接口：data-sc-surface / data-sc-palette / data-sc-layout / data-sc-ui。
 * 标注「兼容性敏感」的段落依赖组件 class，升级 SealChat 后优先检查。
 */

/* =========================================================
 * 1. 设计令牌（夜间默认）
 * ======================================================= */

:root[data-sc-surface] {
  color-scheme: dark;

  --nr-yellow: #f5e400;
  --nr-yellow-ink: #0b0a05;
  --nr-cyan: #00eaff;
  --nr-red: #ff2a6d;
  --nr-violet: #8a3cff;
  --nr-void: #06050a;
  --nr-panel: rgba(12, 11, 20, 0.86);
  --nr-panel-solid: #0d0c16;
  --nr-line: rgba(0, 234, 255, 0.22);
  --nr-line-strong: rgba(0, 234, 255, 0.5);
  --nr-grid: rgba(255, 42, 109, 0.32);
  --nr-scan: rgba(255, 255, 255, 0.035);
  --nr-glow-cyan: 0 0 10px rgba(0, 234, 255, 0.45);
  --nr-glow-yellow: 0 0 14px rgba(245, 228, 0, 0.45);
  --nr-cut: 12px;
  --nr-cut-sm: 7px;
  --nr-hud-font: "JetBrains Mono", "Cascadia Code", "Fira Code", "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  --nr-display-font: "Orbitron", "Rajdhani", "Bahnschrift", "DIN Alternate", "Agency FB", "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;

  --sc-bg-page: var(--nr-void);
  --sc-bg-surface: #0b0a12;
  --sc-bg-header: rgba(8, 7, 14, 0.94);
  --sc-bg-sidebar: rgba(9, 8, 15, 0.92);
  --sc-bg-input: #0a0912;
  --sc-bg-elevated: #110f1c;
  --sc-bg-layer: #0c0b15;
  --sc-bg-layer-strong: rgba(13, 12, 22, 0.97);
  --sc-bg-hover: rgba(0, 234, 255, 0.08);
  --sc-bg-active: rgba(245, 228, 0, 0.12);

  --sc-fg-primary: #eafcff;
  --sc-fg-muted: #8b93a8;
  --sc-text-primary: #eafcff;
  --sc-text-secondary: #8b93a8;

  --sc-border-mute: rgba(0, 234, 255, 0.16);
  --sc-border-strong: rgba(0, 234, 255, 0.42);

  --primary-color: #00eaff;
  --primary-color-hover: #f5e400;
  --sc-action-ribbon-hover-text: #06050a;

  --sc-badge-bg: rgba(245, 228, 0, 0.14);
  --sc-badge-text: #fff7a3;
  --sc-sidebar-hover: rgba(0, 234, 255, 0.07);
  --sc-sidebar-active: rgba(245, 228, 0, 0.14);
  --sc-chip-bg: rgba(0, 234, 255, 0.08);

  --sc-scrollbar-size: 6px;
  --sc-scrollbar-thumb: rgba(0, 234, 255, 0.35);
  --sc-scrollbar-thumb-hover: rgba(245, 228, 0, 0.6);

  --sc-font-family: "Rajdhani", "Bahnschrift", "Segoe UI", "PingFang SC", "Microsoft YaHei", "Noto Sans SC", "Source Han Sans SC", Arial, sans-serif;
  --sc-code-font: var(--nr-hud-font);

  --custom-chat-ic-bg: rgba(10, 18, 30, 0.74);
  --custom-chat-ooc-bg: rgba(24, 9, 22, 0.62);
  --custom-chat-stage-bg: transparent;
  --custom-chat-preview-bg: rgba(14, 22, 38, 0.92);
  --custom-chat-preview-dot: #00eaff;
  --custom-keyword-bg: rgba(245, 228, 0, 0.16);
  --custom-keyword-border: #f5e400;
  --keyword-bg: rgba(245, 228, 0, 0.16);
  --keyword-border-color: #f5e400;

  --chat-stage-bg: transparent;
  --chat-ic-bg: rgba(10, 18, 30, 0.74);
  --chat-ooc-bg: rgba(24, 9, 22, 0.62);
  --chat-preview-bg: rgba(14, 22, 38, 0.92);
  --chat-preview-dot: #00eaff;
  --chat-preview-dot-ic: #00eaff;
  --chat-preview-dot-ooc: #ff2a6d;
  --chat-text-primary: #eafcff;
  --chat-text-secondary: #8b93a8;
  --chat-border-mute: rgba(0, 234, 255, 0.14);
  --chat-bubble-border: rgba(0, 234, 255, 0.3);
  --chat-ooc-border: rgba(255, 42, 109, 0.32);
  --chat-message-shadow: none;
  --chat-dice-result-shadow: 0 0 0 1px rgba(245, 228, 0, 0.35), 0 0 16px rgba(245, 228, 0, 0.2);
  --chat-archived-bg: rgba(80, 80, 96, 0.22);
  --chat-archived-border: rgba(139, 147, 168, 0.2);
  --chat-whisper-accent: #8a3cff;
  --chat-whisper-surface: rgba(138, 60, 255, 0.07);
  --chat-whisper-bg: rgba(138, 60, 255, 0.07);
  --chat-whisper-border: rgba(138, 60, 255, 0.4);
  --chat-whisper-tag-bg: rgba(138, 60, 255, 0.2);
  --chat-whisper-tag-fg: #e2d0ff;
  --chat-inline-code-bg: rgba(245, 228, 0, 0.08);
  --chat-inline-code-fg: #fff27a;
  --chat-inline-code-border: rgba(245, 228, 0, 0.35);
  --chat-editing-preview-bg: rgba(14, 22, 38, 0.95);
  --chat-editing-preview-ic-bg: rgba(10, 18, 30, 0.95);
  --chat-editing-preview-ooc-bg: rgba(30, 10, 26, 0.95);
  --chat-live-preview-ic-bg: rgba(10, 18, 30, 0.9);
  --chat-live-preview-ooc-bg: rgba(30, 10, 26, 0.9);

  --audio-panel-surface: rgba(10, 9, 18, 0.97);
  --audio-panel-border: rgba(0, 234, 255, 0.26);
  --audio-panel-shadow: 0 0 0 1px rgba(245, 228, 0, 0.08), 0 24px 50px rgba(0, 0, 0, 0.6);
  --audio-card-surface: rgba(16, 14, 28, 0.92);
  --audio-card-border: rgba(255, 42, 109, 0.22);
  --audio-progress-track: rgba(139, 147, 168, 0.16);
  --audio-progress-buffer: rgba(0, 234, 255, 0.28);

  --sc-glass-bg: rgba(10, 9, 18, 0.72);
  --sc-glass-solid: rgb(10, 9, 18);
  --sc-glass-border: rgba(0, 234, 255, 0.24);
  --sc-glass-shadow: 0 18px 44px rgba(0, 0, 0, 0.5);
  --sc-glass-blur: 12px;
  --sc-glass-saturate: 150%;
  --sc-glass-contrast: 110%;
}

/* =========================================================
 * 2. 日间：镀铬白昼
 * ======================================================= */

:root[data-sc-palette='day'] {
  color-scheme: light;

  --nr-yellow: #f2dc00;
  --nr-yellow-ink: #0b0a05;
  --nr-cyan: #0089a8;
  --nr-red: #d60f52;
  --nr-violet: #6a1fd6;
  --nr-void: #e7e5de;
  --nr-panel: rgba(244, 243, 238, 0.9);
  --nr-panel-solid: #f4f3ee;
  --nr-line: rgba(11, 10, 16, 0.18);
  --nr-line-strong: rgba(11, 10, 16, 0.55);
  --nr-grid: rgba(214, 15, 82, 0.2);
  --nr-scan: rgba(0, 0, 0, 0.025);
  --nr-glow-cyan: none;
  --nr-glow-yellow: none;

  --sc-bg-page: #e7e5de;
  --sc-bg-surface: #f4f3ee;
  --sc-bg-header: rgba(244, 243, 238, 0.96);
  --sc-bg-sidebar: rgba(236, 234, 227, 0.96);
  --sc-bg-input: #fbfaf6;
  --sc-bg-elevated: #fbfaf6;
  --sc-bg-layer: #efede6;
  --sc-bg-layer-strong: rgba(246, 245, 240, 0.97);
  --sc-bg-hover: rgba(0, 137, 168, 0.08);
  --sc-bg-active: rgba(242, 220, 0, 0.3);

  --sc-fg-primary: #0b0a10;
  --sc-fg-muted: #4d5060;
  --sc-text-primary: #0b0a10;
  --sc-text-secondary: #4d5060;
  --chat-text-primary: #0b0a10;
  --chat-text-secondary: #4d5060;

  --sc-border-mute: rgba(11, 10, 16, 0.14);
  --sc-border-strong: rgba(11, 10, 16, 0.4);

  --primary-color: #0089a8;
  --primary-color-hover: #d60f52;
  --sc-action-ribbon-hover-text: #0b0a05;

  --sc-badge-bg: rgba(242, 220, 0, 0.5);
  --sc-badge-text: #0b0a05;
  --sc-sidebar-hover: rgba(0, 137, 168, 0.08);
  --sc-sidebar-active: rgba(242, 220, 0, 0.45);
  --sc-chip-bg: rgba(11, 10, 16, 0.06);
  --sc-scrollbar-thumb: rgba(11, 10, 16, 0.3);
  --sc-scrollbar-thumb-hover: rgba(214, 15, 82, 0.6);

  --custom-chat-ic-bg: rgba(255, 255, 255, 0.78);
  --custom-chat-ooc-bg: rgba(250, 236, 242, 0.72);
  --custom-chat-preview-bg: #ffffff;
  --custom-chat-preview-dot: #0089a8;
  --custom-keyword-bg: rgba(242, 220, 0, 0.45);
  --custom-keyword-border: #0b0a10;
  --keyword-bg: rgba(242, 220, 0, 0.45);
  --keyword-border-color: #0b0a10;

  --chat-ic-bg: rgba(255, 255, 255, 0.78);
  --chat-ooc-bg: rgba(250, 236, 242, 0.72);
  --chat-preview-bg: #ffffff;
  --chat-preview-dot: #0089a8;
  --chat-preview-dot-ic: #0089a8;
  --chat-preview-dot-ooc: #d60f52;
  --chat-border-mute: rgba(11, 10, 16, 0.12);
  --chat-bubble-border: rgba(11, 10, 16, 0.3);
  --chat-ooc-border: rgba(214, 15, 82, 0.3);
  --chat-dice-result-shadow: 0 0 0 1px rgba(11, 10, 16, 0.4);
  --chat-whisper-accent: #6a1fd6;
  --chat-whisper-surface: rgba(106, 31, 214, 0.06);
  --chat-whisper-bg: rgba(106, 31, 214, 0.06);
  --chat-whisper-border: rgba(106, 31, 214, 0.3);
  --chat-whisper-tag-bg: rgba(106, 31, 214, 0.12);
  --chat-whisper-tag-fg: #3d0f80;
  --chat-inline-code-bg: #0b0a10;
  --chat-inline-code-fg: #f2dc00;
  --chat-inline-code-border: #0b0a10;
  --chat-editing-preview-bg: #ffffff;
  --chat-editing-preview-ic-bg: #ffffff;
  --chat-editing-preview-ooc-bg: #fbeff4;
  --chat-live-preview-ic-bg: rgba(255, 255, 255, 0.92);
  --chat-live-preview-ooc-bg: rgba(251, 239, 244, 0.92);

  --audio-panel-surface: rgba(246, 245, 240, 0.98);
  --audio-panel-border: rgba(11, 10, 16, 0.2);
  --audio-panel-shadow: 6px 6px 0 rgba(11, 10, 16, 0.12);
  --audio-card-surface: #ffffff;
  --audio-card-border: rgba(214, 15, 82, 0.2);
  --audio-progress-track: rgba(11, 10, 16, 0.1);
  --audio-progress-buffer: rgba(0, 137, 168, 0.25);

  --sc-glass-bg: rgba(246, 245, 240, 0.8);
  --sc-glass-solid: rgb(246, 245, 240);
  --sc-glass-border: rgba(11, 10, 16, 0.18);
  --sc-glass-shadow: 6px 6px 0 rgba(11, 10, 16, 0.1);
}

/* =========================================================
 * 3. 画布：透视网格地面 + 扫描线 + 暗角
 * ======================================================= */

:root[data-sc-surface] body {
  background:
    radial-gradient(ellipse 70% 45% at 50% 108%, rgba(255, 42, 109, 0.28), transparent 70%),
    radial-gradient(ellipse 60% 40% at 12% -5%, rgba(0, 234, 255, 0.12), transparent 70%),
    var(--sc-bg-page);
  color: var(--sc-text-primary);
}

:root[data-sc-palette='day'] body {
  background:
    radial-gradient(ellipse 70% 45% at 50% 108%, rgba(214, 15, 82, 0.1), transparent 70%),
    repeating-linear-gradient(-45deg, transparent 0 22px, rgba(11, 10, 16, 0.025) 22px 23px),
    var(--sc-bg-page);
}

/* 透视网格地面：只在大画布页面显示，聊天面板半透明时可以透出来 */
:root[data-sc-surface] body::before {
  content: "";
  position: fixed;
  left: -50%;
  right: -50%;
  bottom: -2px;
  height: 46vh;
  z-index: 0;
  pointer-events: none;
  background-image:
    linear-gradient(var(--nr-grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--nr-grid) 1px, transparent 1px);
  background-size: 64px 40px;
  transform: perspective(380px) rotateX(62deg);
  transform-origin: 50% 100%;
  mask-image: linear-gradient(to top, #000 10%, transparent 92%);
  -webkit-mask-image: linear-gradient(to top, #000 10%, transparent 92%);
  animation: nr-grid-run 3.6s linear infinite;
}

/* 扫描线覆盖层 */
:root[data-sc-surface] body::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 2147483000;
  pointer-events: none;
  background: repeating-linear-gradient(to bottom, var(--nr-scan) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
}

@keyframes nr-grid-run {
  from { background-position: 0 0, 0 0; }
  to { background-position: 0 40px, 0 0; }
}

/* Naive 布局层透明，让画布露出来（兼容性敏感：.n-layout*） */
:root[data-sc-surface] .sc-app-shell,
:root[data-sc-surface] .sc-app-shell .n-layout,
:root[data-sc-surface] .sc-app-shell .n-layout-scroll-container,
:root[data-sc-surface] .sc-app-shell .n-layout-sider,
:root[data-sc-surface] .sc-app-shell .n-layout-header {
  --n-color: transparent !important;
  background-color: transparent !important;
}

:root[data-sc-surface] #app,
:root[data-sc-surface] [data-sc-ui='app'] {
  position: relative;
  z-index: 1;
}

/* =========================================================
 * 4. 顶栏 / 侧栏 / 频道列表
 * ======================================================= */

[data-sc-ui='header'] {
  position: relative;
  background:
    linear-gradient(90deg, var(--nr-yellow) 0 4px, transparent 4px),
    linear-gradient(180deg, rgba(0, 234, 255, 0.05), transparent),
    var(--sc-bg-header) !important;
  border-bottom: 1px solid var(--nr-line-strong) !important;
  box-shadow: 0 1px 0 rgba(255, 42, 109, 0.35), 0 10px 30px rgba(0, 0, 0, 0.35);
}

/* 顶栏右下角的警示条纹 */
[data-sc-ui='header']::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: -5px;
  width: min(34vw, 300px);
  height: 4px;
  pointer-events: none;
  background: repeating-linear-gradient(-45deg, var(--nr-yellow) 0 6px, transparent 6px 12px);
  clip-path: polygon(6px 0, 100% 0, 100% 100%, 0 100%);
  opacity: 0.9;
}

/* 兼容性敏感：频道标题 */
[data-sc-ui='header'] .sc-channel-title {
  font-family: var(--nr-display-font);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--sc-text-primary);
  text-shadow: -1.5px 0 rgba(255, 42, 109, 0.75), 1.5px 0 rgba(0, 234, 255, 0.75);
}

:root[data-sc-palette='day'] [data-sc-ui='header'] .sc-channel-title {
  text-shadow: -1px 0 rgba(214, 15, 82, 0.55), 1px 0 rgba(0, 137, 168, 0.55);
}

[data-sc-ui='header'] .sc-icon-button {
  border-radius: 0 !important;
  clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 6px, 100% 100%, 6px 100%, 0 calc(100% - 6px));
  transition: background-color 0.15s ease, color 0.15s ease;
}

[data-sc-ui='header'] .sc-icon-button:hover {
  background: var(--nr-yellow) !important;
  color: var(--nr-yellow-ink) !important;
}

[data-sc-ui='sidebar'] {
  position: relative;
  background:
    linear-gradient(180deg, rgba(0, 234, 255, 0.05), transparent 30%),
    repeating-linear-gradient(0deg, transparent 0 3px, rgba(0, 234, 255, 0.018) 3px 4px),
    var(--sc-bg-sidebar) !important;
  border-right: 1px solid var(--nr-line);
  box-shadow: inset -1px 0 0 rgba(255, 42, 109, 0.18);
}

[data-sc-ui='channel-list'] {
  gap: 4px;
  counter-reset: nr-ch;
}

/* 兼容性敏感：.sider-item / .channel-item-title */
[data-sc-ui='channel-list'] .sider-item {
  position: relative;
  border-radius: 0 !important;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
  border-left: 2px solid transparent;
  font-family: var(--nr-display-font);
  letter-spacing: 0.04em;
  transition: background-color 0.14s ease, color 0.14s ease, border-color 0.14s ease, padding-left 0.14s ease;
}

[data-sc-ui='channel-list'] .sider-item:hover {
  background: var(--sc-bg-hover) !important;
  border-left-color: var(--nr-cyan);
  padding-left: 0.35rem;
}

[data-sc-ui='channel-list'] .sider-item.active {
  background: var(--nr-yellow) !important;
  color: var(--nr-yellow-ink) !important;
  border-left-color: var(--nr-red);
  box-shadow: var(--nr-glow-yellow);
}

[data-sc-ui='channel-list'] .sider-item.active :is(.channel-item-title, .n-icon, span) {
  color: var(--nr-yellow-ink) !important;
}

[data-sc-ui='channel-list'] .sider-item.active::after {
  content: "LIVE";
  position: absolute;
  right: 14px;
  top: 50%;
  transform: translateY(-50%);
  padding: 0 4px;
  font: 700 9px/14px var(--nr-hud-font);
  letter-spacing: 0.12em;
  color: var(--nr-yellow);
  background: var(--nr-yellow-ink);
}

/* 兼容性敏感：侧栏世界快捷按钮与底部操作 */
[data-sc-ui='sidebar'] .sc-sidebar__world-action-button,
[data-sc-ui='sidebar'] .sidebar-footer-actions .n-button {
  border-radius: 0 !important;
  font-family: var(--nr-hud-font);
  font-size: 11px;
  letter-spacing: 0.04em;
}

[data-sc-ui='sidebar'] .sc-sidebar__world-action-button:hover {
  color: var(--nr-yellow) !important;
}

/* =========================================================
 * 5. 消息
 * ======================================================= */

:root[data-sc-surface] [data-sc-ui='message-list'],
:root[data-sc-surface] .chat-pinned-zone {
  --chat-ic-bg: var(--custom-chat-ic-bg);
  --chat-ooc-bg: var(--custom-chat-ooc-bg);
  --chat-live-preview-ic-bg: var(--chat-ic-bg);
  --chat-live-preview-ooc-bg: var(--chat-ooc-bg);
  background: transparent !important;
}

[data-sc-ui='message'] {
  position: relative;
  transition: background-color 0.15s ease;
}

/* 紧凑布局：数据包行 */
:root[data-sc-surface] [data-sc-ui='message-list'].chat--layout-compact .message-row__surface {
  position: relative;
  border-left: 2px solid transparent;
  background-color: transparent !important;
}

:root[data-sc-surface] [data-sc-ui='message-list'].chat--layout-compact .message-row__surface--tone-ic {
  border-left-color: color-mix(in srgb, var(--nr-cyan) 55%, transparent);
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--nr-cyan) 9%, transparent), transparent 42%),
    var(--chat-ic-bg) !important;
}

:root[data-sc-surface] [data-sc-ui='message-list'].chat--layout-compact .message-row__surface--tone-ooc {
  border-left-color: color-mix(in srgb, var(--nr-red) 45%, transparent);
  background:
    repeating-linear-gradient(-45deg, transparent 0 10px, color-mix(in srgb, var(--nr-red) 4%, transparent) 10px 11px),
    var(--chat-ooc-bg) !important;
}

:root[data-sc-surface] [data-sc-ui='message-list'].chat--layout-compact [data-sc-ui='message']:hover .message-row__surface {
  border-left-color: var(--nr-yellow);
}

/* 兼容性敏感：chat-item 内部结构 */
[data-sc-ui='message'] .chat-item .name {
  font-family: var(--nr-display-font);
  font-weight: 700;
  letter-spacing: 0.06em;
}

[data-sc-ui='message'] .chat-item--ic .title .name::before {
  content: "//";
  margin-right: 0.3em;
  font-family: var(--nr-hud-font);
  color: var(--nr-yellow);
  opacity: 0.85;
}

[data-sc-ui='message'] .chat-item--ooc .title::after {
  content: "OFF-RECORD";
  margin-left: 0.6em;
  padding: 0 5px;
  font: 700 9px/15px var(--nr-hud-font);
  letter-spacing: 0.14em;
  color: var(--nr-red);
  border: 1px solid color-mix(in srgb, var(--nr-red) 55%, transparent);
  vertical-align: 2px;
}

[data-sc-ui='message'] .chat-item--ooc .content {
  font-family: var(--nr-hud-font);
  font-size: 0.92em;
}

[data-sc-ui='message'] .chat-item .time {
  font-family: var(--nr-hud-font);
  letter-spacing: 0.04em;
  color: color-mix(in srgb, var(--nr-cyan) 70%, var(--sc-text-secondary));
}

/* 头像：切角 + 霓虹描边 */
[data-sc-ui='message'] .chat-item__avatar :is(.avatar-shell, img) {
  border-radius: 0 !important;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
}

[data-sc-ui='message'] .chat-item__avatar .avatar-shell {
  background: linear-gradient(135deg, var(--nr-cyan), var(--nr-red));
  padding: 2px;
}

/* 气泡布局：切角终端窗 */
:root[data-sc-surface] .chat-item--layout-bubble > .right > .content {
  position: relative;
  border-radius: 0 !important;
  border: 1px solid var(--chat-bubble-border) !important;
