/* =========================================================
 * 10. 脚本增强（需要 theme-neon-runner.js）
 * ======================================================= */

.nr-hud[hidden],
.nr-frame[hidden] {
  display: none !important;
}

/* HUD 状态条：位于顶栏中部的空白区域 */
.nr-hud {
  position: fixed;
  top: 0;
  left: 50%;
  z-index: 2000;
  height: 3.5rem;
  display: flex;
  align-items: center;
  gap: 14px;
  transform: translateX(-50%);
  pointer-events: none;
  font: 600 11px/1 var(--nr-hud-font);
  letter-spacing: 0.12em;
  color: color-mix(in srgb, var(--nr-cyan) 80%, transparent);
  text-transform: uppercase;
  white-space: nowrap;
}

.nr-hud__seg {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  border: 1px solid var(--nr-line);
  background: color-mix(in srgb, var(--sc-bg-header) 70%, transparent);
  clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 6px, 100% 100%, 0 100%);
}

.nr-hud__seg--clock {
  color: var(--nr-yellow);
  border-color: color-mix(in srgb, var(--nr-yellow) 45%, transparent);
  min-width: 9ch;
  justify-content: center;
}

:root[data-sc-palette='day'] .nr-hud__seg--clock {
  color: var(--nr-yellow-ink);
  background: var(--nr-yellow);
  border-color: var(--nr-yellow-ink);
}

:root[data-sc-palette='day'] [data-sc-ui='message'] .chat-item--ic .title .name::before {
  color: var(--nr-red);
}

.nr-hud__dot {
  width: 6px;
  height: 6px;
  background: var(--nr-cyan);
  box-shadow: var(--nr-glow-cyan);
  animation: nr-blink 1.2s steps(2) infinite;
}

.nr-hud__seg--rx b {
  color: var(--nr-red);
  font-weight: 700;
}

@keyframes nr-blink {
  50% { opacity: 0.2; }
}

/* 视口四角定位框 */
.nr-frame {
  position: fixed;
  inset: 6px;
  z-index: 1999;
  pointer-events: none;
}

.nr-frame i {
  position: absolute;
  width: 18px;
  height: 18px;
  border: 0 solid color-mix(in srgb, var(--nr-cyan) 65%, transparent);
}

.nr-frame i:nth-child(1) { left: 0; top: 0; border-width: 2px 0 0 2px; }
.nr-frame i:nth-child(2) { right: 0; top: 0; border-width: 2px 2px 0 0; }
.nr-frame i:nth-child(3) { left: 0; bottom: 0; border-width: 0 0 2px 2px; }
.nr-frame i:nth-child(4) { right: 0; bottom: 0; border-width: 0 2px 2px 0; border-color: var(--nr-yellow); }

/* 开机序列 */
.nr-boot {
  position: fixed;
  inset: 0;
  z-index: 2147483001;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 6vh 6vw;
  pointer-events: none;
  background: var(--nr-void);
  font: 500 13px/1.7 var(--nr-hud-font);
  color: var(--nr-cyan);
  animation: nr-boot-out 0.45s ease forwards;
  animation-delay: var(--nr-boot-ms, 1500ms);
}

.nr-boot__line { opacity: 0; animation: nr-line-in 0.05s linear forwards; }
.nr-boot__line--ok::after { content: " [ OK ]"; color: var(--nr-yellow); }
.nr-boot__logo {
  margin-bottom: 18px;
  font: 800 clamp(28px, 6vw, 64px)/1 var(--nr-display-font);
  letter-spacing: 0.12em;
  color: var(--nr-yellow);
  text-shadow: -3px 0 var(--nr-red), 3px 0 var(--nr-cyan);
}

@keyframes nr-line-in { to { opacity: 1; } }
@keyframes nr-boot-out { to { opacity: 0; visibility: hidden; } }

/* 新信号到达：扫描展开 + 闪烁 */
[data-sc-ui='message'].nr-incoming .message-row__surface,
[data-sc-ui='message'].nr-incoming .chat-item--layout-bubble > .right > .content {
  animation: nr-incoming 0.7s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

[data-sc-ui='message'].nr-incoming::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 2px;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, var(--nr-yellow), var(--nr-cyan), transparent);
  box-shadow: var(--nr-glow-yellow);
  animation: nr-sweep 0.7s ease-out forwards;
}

@keyframes nr-incoming {
  0% { clip-path: inset(0 0 100% 0); filter: brightness(2.2) saturate(0); }
  35% { clip-path: inset(0 0 0 0); filter: brightness(1.6); transform: translateX(-3px); }
  45% { transform: translateX(2px); }
  55% { transform: none; filter: none; }
  70% { opacity: 0.6; }
  100% { opacity: 1; }
}

@keyframes nr-sweep {
  from { transform: translateY(0); opacity: 1; }
  to { transform: translateY(var(--nr-row-h, 60px)); opacity: 0; }
}

/* 频道标题故障切片 */
[data-sc-ui='header'] .sc-channel-title.nr-glitch {
  position: relative;
  animation: nr-jitter 0.5s steps(2) 1;
}

[data-sc-ui='header'] .sc-channel-title.nr-glitch::before,
[data-sc-ui='header'] .sc-channel-title.nr-glitch::after {
  content: attr(data-nr-text);
  position: absolute;
  inset: 0;
  pointer-events: none;
}

[data-sc-ui='header'] .sc-channel-title.nr-glitch::before {
  color: var(--nr-red);
  clip-path: inset(10% 0 55% 0);
  transform: translateX(-4px);
  animation: nr-slice 0.5s steps(3) 1;
}

[data-sc-ui='header'] .sc-channel-title.nr-glitch::after {
  color: var(--nr-cyan);
  clip-path: inset(60% 0 5% 0);
  transform: translateX(4px);
  animation: nr-slice 0.5s steps(3) reverse 1;
}

@keyframes nr-jitter {
  0% { transform: translate(0); }
  25% { transform: translate(-2px, 1px); }
  50% { transform: translate(2px, -1px); }
  100% { transform: translate(0); }
}

@keyframes nr-slice {
  0% { clip-path: inset(5% 0 70% 0); }
  33% { clip-path: inset(45% 0 30% 0); }
  66% { clip-path: inset(75% 0 5% 0); }
  100% { clip-path: inset(30% 0 45% 0); }
}

/* 全局短暂色散 */
:root[data-nr-glitch='on'] [data-sc-ui='header'],
:root[data-nr-glitch='on'] [data-sc-ui='sidebar'] {
  filter: drop-shadow(-2px 0 rgba(255, 42, 109, 0.6)) drop-shadow(2px 0 rgba(0, 234, 255, 0.6));
}

:root[data-nr-glitch='on'] .nr-hud {
  transform: translateX(calc(-50% + 3px)) skewX(-8deg);
}

/* =========================================================
 * 11. 紧凑布局 / 窄屏 / 减少动画
 * ======================================================= */

:root[data-sc-layout='compact'] [data-sc-ui='message'] .chat-item--ooc .title::after {
  font-size: 8px;
}

@media (max-width: 960px) {
  .nr-hud { display: none; }
}

@media (max-width: 640px) {
  :root[data-sc-surface] body::before {
    height: 30vh;
    background-size: 44px 30px;
  }

  [data-sc-ui='header']::after { width: 90px; }

  [data-sc-ui='channel-list'] .sider-item.active::after { display: none; }

  [data-sc-ui='message'] .chat-item--ooc .title::after { display: none; }

  :root[data-sc-surface] .chat-item--layout-bubble > .right > .content {
    --nr-cut: 8px;
  }

  .nr-frame { display: none; }

  :root[data-sc-surface='auth'] .sign-in-content {
    clip-path: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  :root[data-sc-surface] *:not(.tiptap-performance):not(.twin-layer-message__char):not(.twin-layer-message__char-glyph),
  :root[data-sc-surface] *:not(.tiptap-performance):not(.twin-layer-message__char):not(.twin-layer-message__char-glyph)::before,
  :root[data-sc-surface] *:not(.tiptap-performance):not(.twin-layer-message__char):not(.twin-layer-message__char-glyph)::after {
    scroll-behavior: auto !important;
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }

  :root[data-sc-surface] body::before {
    animation: none !important;
  }

  .nr-boot { display: none; }
}

